struct Point { int x, y; };
struct Rect { Point origin; int w, h; };

// Standard initialization
Point p { 1, 2 };
int arr[] = { 10, 20, 30 };
int arr_zeros[5] {};

// Nested aggregates (C++17 flattening allowed)
Rect r1 { {5, 5}, 100, 50 };
Rect r2 { 5, 5, 100, 50 };

// C++20 Designated Initializers
struct Config { int id; float value; };
Config c1 { .value = 3.14f }; // id defaults to 0
Config c2 { .w = 100, .origin = {0, 0} }; // C++20 designated for struct Rect

// Brace elision for nested arrays
int matrix[2][3] = { {1, 2}, {4, 5} };
